"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[6285],{6291(e){e.exports=JSON.parse('{"tag":{"label":"Binary Search","permalink":"/concepts/tags/binary-search","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"algorithm-design-paradigms/divide-and-conquer-examples-1","title":"Divide and Conquer: Numbers and Searches","description":"This lesson applies the paradigm and its analysis to a first set of classic problems: the factorial, sequential and binary search, the Fibonacci numbers and the greatest common divisor. Some of them show the strength of divide and conquer; others, especially Fibonacci, show what happens when it is applied badly. All of them are implemented, with tests, in the course repository.","permalink":"/concepts/algorithm-design-paradigms/divide-and-conquer-examples-1"},{"id":"foundations-of-algorithms/searching-case-studies","title":"Searching Case Studies","description":"Searching is one of the most frequent operations in computing: looking up a user in a database, a word in a dictionary, a file in a directory, a value in a cache. In this final lesson of the chapter we apply everything we have learnt to three classic search algorithms. For each one we count instructions exactly, analyze the best, worst and average cases, express the result with asymptotic notation and connect it with real measurements.","permalink":"/concepts/foundations-of-algorithms/searching-case-studies"}],"unlisted":false}}')}}]);